<?php
declare(strict_types=1);
if(!defined('HOGAR_INTERNAL')){http_response_code(404);exit;}
$db->exec('CREATE TABLE IF NOT EXISTS roomie_posts(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,intent TEXT NOT NULL,title TEXT NOT NULL,state TEXT NOT NULL,city TEXT NOT NULL,neighborhood TEXT NOT NULL,budget INTEGER NOT NULL,move_in TEXT NOT NULL,description TEXT NOT NULL,contact_type TEXT NOT NULL,contact TEXT NOT NULL,status TEXT NOT NULL DEFAULT "active",created INTEGER NOT NULL,updated INTEGER NOT NULL);CREATE INDEX IF NOT EXISTS roomie_visible ON roomie_posts(status,created);CREATE TABLE IF NOT EXISTS roomie_reports(id INTEGER PRIMARY KEY,post_id TEXT NOT NULL REFERENCES roomie_posts(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,reason TEXT NOT NULL,created INTEGER NOT NULL,resolved_at INTEGER,UNIQUE(post_id,user_id))');
function roomieRow(string $id): ?array {return query('SELECT p.*,u.name AS owner_name,u.status AS owner_status,u.email_verified_at AS owner_verified FROM roomie_posts p JOIN users u ON u.id=p.user_id WHERE p.id=?',[$id])->fetch()?:null;}
function roomieData(array $r,bool $detail=false): array {if($detail)$r['profile_id']=query('SELECT p.id FROM community_profiles p JOIN users u ON u.id=p.user_id WHERE p.user_id=? AND p.visible=1 AND u.status="active" AND u.email_verified_at IS NOT NULL',[$r['user_id']??0])->fetchColumn()?:null;unset($r['user_id'],$r['owner_status'],$r['owner_verified']);$r['budget']=(int)$r['budget'];if(!$detail)unset($r['contact'],$r['contact_type']);return $r;}
function roomieSafety(array $input): void {if(!in_array($input['safety']??null,[true,'1'],true))fail('Confirma que entiendes las precauciones de la comunidad.');requireTerms($input);}
function handleRoomies(string $action,string $method,array $input): void {
 if(!str_starts_with($action,'roomies-')&&!str_starts_with($action,'admin-roomies'))return;
 global $db;
 if($action==='roomies-list'&&$method==='GET'){
  $where=['p.status="active"','u.status="active"'];$args=[];
  foreach(['state','city','neighborhood'] as $field){$v=$_GET[$field]??'';if(!is_string($v)||mb_strlen($v)>100)fail('Revisa la ubicación.');if(trim($v)!==''){$fn=$field==='state'?'state_key':'location_key';$where[]=$fn.'(p.'.$field.')=?';$args[]=$fn($v);}}
  $intent=$_GET['intent']??'';if(!is_string($intent)||!in_array($intent,['','Busco roomie','Busco espacio'],true))fail('Selecciona una búsqueda válida.');if($intent!==''){$where[]='p.intent=?';$args[]=$intent;}
  $budget=$_GET['budget']??'';if($budget!==''){$max=filter_var($budget,FILTER_VALIDATE_INT);if($max===false||$max<1||$max>1000000)fail('Revisa el presupuesto.');$where[]='p.budget<=?';$args[]=$max;}
  $sql=implode(' AND ',$where);$page=max(1,min(10000,(int)($_GET['page']??1)));$count=(int)query('SELECT COUNT(*) FROM roomie_posts p JOIN users u ON u.id=p.user_id WHERE '.$sql,$args)->fetchColumn();$rows=query('SELECT p.*,u.name AS owner_name FROM roomie_posts p JOIN users u ON u.id=p.user_id WHERE '.$sql.' ORDER BY p.created DESC,p.id DESC LIMIT 12 OFFSET '.(($page-1)*12),$args)->fetchAll();reply(['items'=>array_map(fn($p)=>roomieData($p),$rows),'total'=>$count,'page'=>$page,'pages'=>(int)ceil($count/12)]);
 }
 if($action==='roomies-detail'&&$method==='GET'){$p=roomieRow((string)($_GET['id']??''));$viewer=user();if(!$p||(($p['status']!=='active'||$p['owner_status']!=='active')&&(int)$p['user_id']!==(int)($viewer['id']??0)&&!isSuperadmin($viewer)))fail('Esta publicación ya no está disponible.',404);reply(['post'=>roomieData($p,true)]);}
 $u=requireUser();
 if(str_starts_with($action,'admin-roomies')){
  if(!isSuperadmin($u))fail('Acceso reservado al superadmin.',403);
  if($action==='admin-roomies'&&$method==='GET'){
   $q=adminSearch();$status=$_GET['status']??'';if(!is_string($status)||!in_array($status,['','active','paused','archived'],true))fail('Estado inválido.');$where=['1=1'];$args=[];if($q!==''){$where[]='(instr(lower(p.title),lower(?))>0 OR instr(lower(p.city),lower(?))>0)';array_push($args,$q,$q);}if($status!==''){$where[]='p.status=?';$args[]=$status;}$sql=implode(' AND ',$where);$page=max(1,min(10000,(int)($_GET['page']??1)));$total=(int)query('SELECT COUNT(*) FROM roomie_posts p WHERE '.$sql,$args)->fetchColumn();$rows=query('SELECT p.*,u.name AS owner_name,(SELECT COUNT(*) FROM roomie_reports r WHERE r.post_id=p.id AND resolved_at IS NULL) AS open_reports FROM roomie_posts p JOIN users u ON u.id=p.user_id WHERE '.$sql.' ORDER BY p.created DESC LIMIT 20 OFFSET '.(($page-1)*20),$args)->fetchAll();foreach($rows as &$row){$row=roomieData($row,true);$row['reports']=query('SELECT reason,created,resolved_at FROM roomie_reports WHERE post_id=? ORDER BY id DESC LIMIT 30',[$row['id']])->fetchAll();}unset($row);reply(['items'=>$rows,'total'=>$total,'page'=>$page,'pages'=>(int)ceil($total/20)]);
  }
  if($action==='admin-roomies-status'&&$method==='POST'){$id=strvalInput($input,'id',24,24);$status=choice($input,'status',['active','paused','archived']);$p=roomieRow($id);if(!$p)fail('Publicación no encontrada.',404);if($status==='active'&&($p['owner_status']!=='active'||$p['owner_verified']===null))fail('La cuenta debe estar activa y con correo confirmado.');query('UPDATE roomie_posts SET status=?,updated=? WHERE id=?',[$status,time(),$id]);auditAdmin($u,'roomie_'.$status,$id);reply(['ok'=>true]);}
  if($action==='admin-roomies-resolve'&&$method==='POST'){$id=strvalInput($input,'id',24,24);query('UPDATE roomie_reports SET resolved_at=? WHERE post_id=? AND resolved_at IS NULL',[time(),$id]);auditAdmin($u,'roomie_reports_resolved',$id);reply(['ok'=>true]);}
  fail('Operación no disponible.',405);
 }
 if($action==='roomies-mine'&&$method==='GET')reply(['items'=>array_map(fn($p)=>roomieData($p,true),query('SELECT p.*,u.name AS owner_name FROM roomie_posts p JOIN users u ON u.id=p.user_id WHERE p.user_id=? ORDER BY p.created DESC',[$u['id']])->fetchAll())]);
 if($method!=='POST')fail('Operación no disponible.',405);
 if(in_array($action,['roomies-create','roomies-update'],true)){
  requireVerified($u);roomieSafety($input);limitRate('roomie-publish',20,3600);
  $id=$action==='roomies-create'?bin2hex(random_bytes(12)):strvalInput($input,'id',24,24);$old=$action==='roomies-update'?roomieRow($id):null;if($action==='roomies-update'&&(!$old||(int)$old['user_id']!==(int)$u['id']))fail('Publicación no disponible.',404);if($old&&$old['status']==='archived')fail('Esta publicación fue retirada por administración.',403);
  if(!$old&&(int)query('SELECT COUNT(*) FROM roomie_posts WHERE user_id=?',[$u['id']])->fetchColumn()>=20)fail('Puedes mantener hasta 20 publicaciones de comunidad. Edita o pausa las existentes.');
  $intent=choice($input,'intent',['Busco roomie','Busco espacio']);$title=strvalInput($input,'title',8,100);$state=strvalInput($input,'state',2,70);$city=strvalInput($input,'city',2,100);$zone=strvalInput($input,'neighborhood',0,100);$budget=integerInput($input,'budget',1,1000000);$desc=strvalInput($input,'description',30,2500);$date=strvalInput($input,'move_in',0,10);if($date!==''&&(!preg_match('/^([0-9]{4})-([0-9]{2})-([0-9]{2})$/D',$date,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1])))fail('Revisa la fecha de mudanza.');
  $type=choice($input,'contact_type',['Mensajes','WhatsApp','Teléfono','Correo']);$contact=$type==='Mensajes'?'':strvalInput($input,'contact',5,254);if($type==='Mensajes'){if(!query('SELECT id FROM community_profiles WHERE user_id=? AND visible=1',[$u['id']])->fetchColumn())fail('Crea y muestra tu perfil social para recibir mensajes sin publicar un contacto externo.');}elseif($type==='Correo'){if(!filter_var($contact,FILTER_VALIDATE_EMAIL))fail('Escribe un correo de contacto válido.');}else{$contact=preg_replace('/[^0-9]/','',$contact);if(strlen($contact)<10||strlen($contact)>15)fail('Usa un teléfono de 10 a 15 dígitos.');if(strlen($contact)===10)$contact='52'.$contact;}
  if(!in_array($input['contact_consent']??null,[true,'1'],true))fail('Autoriza mostrar tu nombre y contacto.');$status=choice($input,'status',['active','paused']);$now=time();$db->beginTransaction();try{if($old)query('UPDATE roomie_posts SET intent=?,title=?,state=?,city=?,neighborhood=?,budget=?,move_in=?,description=?,contact_type=?,contact=?,status=?,updated=? WHERE id=?',[$intent,$title,$state,$city,$zone,$budget,$date,$desc,$type,$contact,$status,$now,$id]);else query('INSERT INTO roomie_posts(id,user_id,intent,title,state,city,neighborhood,budget,move_in,description,contact_type,contact,status,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$u['id'],$intent,$title,$state,$city,$zone,$budget,$date,$desc,$type,$contact,$status,$now,$now]);recordTerms((int)$u['id'],$old?'roomie-update':'roomie-create',$id);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}reply(['post'=>roomieData(roomieRow($id),true)],$old?200:201);
 }
 if($action==='roomies-status'){$id=strvalInput($input,'id',24,24);$status=choice($input,'status',['active','paused']);$p=roomieRow($id);if(!$p||(int)$p['user_id']!==(int)$u['id'])fail('Publicación no disponible.',404);if($p['status']==='archived')fail('Publicación retirada por administración.',403);if($status==='active'){requireVerified($u);roomieSafety($input);}$db->beginTransaction();query('UPDATE roomie_posts SET status=?,updated=? WHERE id=?',[$status,time(),$id]);if($status==='active')recordTerms((int)$u['id'],'roomie-reactivate',$id);$db->commit();reply(['ok'=>true]);}
 if($action==='roomies-report'){requireVerified($u);limitRate('roomie-report',10,3600);$id=strvalInput($input,'id',24,24);$reason=strvalInput($input,'reason',10,1000);$p=roomieRow($id);if(!$p||$p['status']!=='active'||$p['owner_status']!=='active')fail('Publicación no disponible.',404);query('INSERT INTO roomie_reports(post_id,user_id,reason,created) VALUES(?,?,?,?) ON CONFLICT(post_id,user_id) DO UPDATE SET reason=excluded.reason,created=excluded.created,resolved_at=NULL',[$id,$u['id'],$reason,time()]);reply(['ok'=>true]);}
 fail('Operación no disponible.',404);
}
